def compute(vars):
    current_2019 = vars["v1"]
    current_2018 = vars["v2"]
    average_current_maturities = (current_2019 + current_2018) / 2

    return {
        "value": average_current_maturities,
        "trace": {
            "current_2019": current_2019,
            "current_2018": current_2018,
            "average_current_maturities": average_current_maturities,
            "output_meta": {
                "currency": "$",
                "scale": "thousand",
                "unit": None
            }
        }
    }
